import time

def retry_call(fn, attempts, sleep):
    delay = 1
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            print(f"Retrying in {delay} s")
            time.sleep(delay)
            delay *= 2
    raise e
```

```python
def retry_call(fn, attempts, sleep):
    """
    Call a function until it succeeds, with exponential backoff on failure.

    Args:
        fn (function): The function to call.
        attempts (int): The maximum number of attempts.
        sleep (function): A function that takes an integer argument and sleeps for that many seconds.

    Returns:
        The result of the function call.
    """
    delay = 1
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            if attempt < attempts - 1:
                sleep(delay)
                delay *= 2
            else:
                raise e
```

