```python
def unique_usernames(names):
    seen, out = set(), []
    for name in names:
        key = name.lower().replace(".", "")
        if key not in seen:
            seen.add(key)
            out.append(key)
    return out
```

```python
def unique_usernames(names):
    seen, out = set(), []
    for name in names:
        key = name.lower().replace(".", "")
        if key not in seen:
            seen.add(key)
            out.append(key)
    return out
